ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    PrixTotale: (vars.PrixTotale default 0) + (payload.total as Number) 
}

%dw 2.0
output application/json
var priceList = vars.priceList default []  // Assurez-vous que priceList est une liste
---
{
  "order": {
    "totals": {
      "subtotal": vars.PrixTotale as String,
      "total": vars.PrixTotale as String

      },
    "billingInfo": vars.inputpayload.order.billingInfo,
    "shippingInfo": {
      "shipmentDetails": {
        "address": {
          "email": vars.inputpayload.order.shippingInfo.shipmentDetails.address.email,
          "fullName": {
            "firstName": vars.inputpayload.order.shippingInfo.shipmentDetails.address.fullName.firstName,
            "lastName": vars.inputpayload.order.shippingInfo.shipmentDetails.address.fullName.lastName
          },
          "country": vars.inputpayload.order.shippingInfo.shipmentDetails.address.country,
          "city": vars.inputpayload.order.shippingInfo.shipmentDetails.address.city,
          "phone": vars.inputpayload.order.shippingInfo.shipmentDetails.address.phone
        }
      }
    },
    "paymentStatus": "NOT_PAID",
    "lineItems": vars.inputpayload.order.lineItems map (item, index) -> {
      "quantity": item.quantity,
      "name": item.name,
      "priceData": {
        "price": priceList[index] as String default "0.0"  // Associez le prix en utilisant l'index
      }
    },
    "channelInfo": {
      "type": "WEB"
    }
  }
}
